        ["Experimental sandbox starts manually from the repository tab. Select reviewed files and configure an API provider first."] = ["Experimental sandbox starts manually from the repository tab. Select reviewed files and configure an API provider first.", "De experimentele sandbox start handmatig vanaf de repositorytab. Selecteer gecontroleerde bestanden en configureer eerst een API-provider.", "Die experimentelle Sandbox wird manuell im Repository-Tab gestartet. Wählen Sie geprüfte Dateien und konfigurieren Sie einen API-Anbieter.", "Le bac à sable expérimental démarre manuellement depuis l’onglet du dépôt. Sélectionnez les fichiers vérifiés et configurez un fournisseur API."],
        ["Revoking permission stops the repository sandbox. Host API keys are never shown here."] = ["Revoking permission stops the repository sandbox. Host API keys are never shown here.", "Toestemming intrekken stopt de repositorysandbox. API-sleutels van de host worden hier nooit getoond.", "Das Entziehen einer Berechtigung stoppt die Repository-Sandbox. Host-API-Schlüssel werden hier nie angezeigt.", "Révoquer une autorisation arrête le bac à sable du dépôt. Les clés API de l’hôte ne sont jamais affichées ici."],
        ["Discard captured sandbox changes"] = ["Discard captured sandbox changes", "Vastgelegde sandboxwijzigingen weggooien", "Erfasste Sandbox-Änderungen verwerfen", "Supprimer les modifications du bac à sable enregistrées"],
        ["Discard the captured changes? They will no longer be available for review."] = ["Discard the captured changes? They will no longer be available for review.", "Vastgelegde wijzigingen weggooien? Ze zijn daarna niet meer beschikbaar voor beoordeling.", "Erfasste Änderungen verwerfen? Sie sind danach nicht mehr zur Prüfung verfügbar.", "Supprimer les modifications enregistrées ? Elles ne seront plus disponibles pour examen."],
        ["Allow sandbox network access?"] = ["Allow sandbox network access?", "Sandbox-netwerktoegang toestaan?", "Sandbox-Netzwerkzugriff erlauben?", "Autoriser l’accès réseau du bac à sable ?"],
        ["Allowing this destination may send repository content to it. The permission is saved for this repository and can be revoked."] = ["Allowing this destination may send repository content to it. The permission is saved for this repository and can be revoked.", "Toestemming voor deze bestemming kan repository-inhoud ernaartoe versturen. De toestemming wordt voor deze repository opgeslagen en kan worden ingetrokken.", "Die Freigabe dieses Ziels kann Repository-Inhalte dorthin übertragen. Die Berechtigung wird für dieses Repository gespeichert und kann widerrufen werden.", "Autoriser cette destination peut lui transmettre le contenu du dépôt. L’autorisation est enregistrée pour ce dépôt et peut être révoquée."],
        ["Allow destination"] = ["Allow destination", "Bestemming toestaan", "Ziel erlauben", "Autoriser la destination"],
        ["Reject"] = ["Reject", "Weigeren", "Ablehnen", "Refuser"],
        ["Review sandbox changes"] = ["Review sandbox changes", "Sandboxwijzigingen beoordelen", "Sandbox-Änderungen prüfen", "Examiner les modifications du bac à sable"],
        ["Selected modifications replace existing files after conflict checks and backup. Deletions and new files are not applied."] = ["Selected modifications replace existing files after conflict checks and backup. Deletions and new files are not applied.", "Geselecteerde wijzigingen vervangen bestaande bestanden na conflictcontrole en back-up. Verwijderingen en nieuwe bestanden worden niet toegepast.", "Ausgewählte Änderungen ersetzen vorhandene Dateien nach Konfliktprüfung und Sicherung. Löschungen und neue Dateien werden nicht angewendet.", "Les modifications sélectionnées remplacent les fichiers existants après vérification des conflits et sauvegarde. Les suppressions et nouveaux fichiers ne sont pas appliqués."],
        ["No captured sandbox changes."] = ["No captured sandbox changes.", "Geen vastgelegde sandboxwijzigingen.", "Keine erfassten Sandbox-Änderungen.", "Aucune modification du bac à sable enregistrée."],
        ["Modification applied; original backed up."] = ["Modification applied; original backed up.", "Wijziging toegepast; origineel geback-upt.", "Änderung angewendet; Original gesichert.", "Modification appliquée ; original sauvegardé."],
        ["Deletion captured but not applied."] = ["Deletion captured but not applied.", "Verwijdering vastgelegd maar niet toegepast.", "Löschung erfasst, aber nicht angewendet.", "Suppression enregistrée mais non appliquée."],
        ["Captured file content"] = ["Captured file content", "Vastgelegde bestandsinhoud", "Erfasster Dateiinhalt", "Contenu du fichier enregistré"],
        ["Original backups"] = ["Original backups", "Back-ups van originelen", "Originalsicherungen", "Sauvegardes des originaux"],
        ["Apply selected modifications"] = ["Apply selected modifications", "Geselecteerde wijzigingen toepassen", "Ausgewählte Änderungen anwenden", "Appliquer les modifications sélectionnées"],
        ["Binary content cannot be previewed."] = ["Binary content cannot be previewed.", "Binaire inhoud kan niet worden weergegeven.", "Binärinhalt kann nicht angezeigt werden.", "Le contenu binaire ne peut pas être prévisualisé."],
        ["Preview shortened."] = ["Preview shortened.", "Voorbeeld ingekort.", "Vorschau gekürzt.", "Aperçu raccourci."],
        ["Could not apply sandbox modification. Review conflicts and backups before retrying."] = ["Could not apply sandbox modification. Review conflicts and backups before retrying.", "Sandboxwijziging toepassen mislukt. Controleer conflicten en back-ups voordat je opnieuw probeert.", "Sandbox-Änderung konnte nicht angewendet werden. Prüfen Sie Konflikte und Sicherungen vor einem erneuten Versuch.", "Impossible d’appliquer la modification du bac à sable. Vérifiez les conflits et sauvegardes avant de réessayer."],
        ["OpenCode sandbox integration is not ready yet. Recorded permissions do not enable sandbox execution."] = ["OpenCode sandbox integration is not ready yet. Recorded permissions do not enable sandbox execution.", "De OpenCode-sandboxintegratie is nog niet klaar. Opgeslagen toestemmingen maken de sandbox nog niet beschikbaar.", "Die OpenCode-Sandbox-Integration ist noch nicht fertig. Gespeicherte Berechtigungen aktivieren die Sandbox nicht.", "L’intégration du bac à sable OpenCode n’est pas encore prête. Les autorisations enregistrées n’activent pas son exécution."],
        ["No sandbox permissions recorded."] = ["No sandbox permissions recorded.", "Geen sandbox-toestemmingen opgeslagen.", "Keine Sandbox-Berechtigungen gespeichert.", "Aucune autorisation de bac à sable enregistrée."],
        ["Permission revoked"] = ["Permission revoked", "Toestemming ingetrokken", "Berechtigung entzogen", "Autorisation révoquée"],
