        ["Could not load sandbox permissions."] = ["Could not load sandbox permissions.", "Sandbox-toestemmingen laden mislukt.", "Sandbox-Berechtigungen konnten nicht geladen werden.", "Impossible de charger les autorisations du bac à sable."],
        ["Could not revoke sandbox permission."] = ["Could not revoke sandbox permission.", "Sandbox-toestemming intrekken mislukt.", "Sandbox-Berechtigung konnte nicht entzogen werden.", "Impossible de révoquer l’autorisation du bac à sable."],
        ["Sandbox unavailable"] = ["Sandbox unavailable", "Sandbox niet beschikbaar", "Sandbox nicht verfügbar", "Bac à sable indisponible"],
        ["Sandbox requested, but not active: OpenCode is blocked."] = ["Sandbox requested, but not active: OpenCode is blocked.", "Sandbox ingeschakeld, maar niet actief: OpenCode is geblokkeerd.", "Sandbox angefordert, aber nicht aktiv: OpenCode ist blockiert.", "Bac à sable demandé mais inactif : OpenCode est bloqué."],
        ["Sandbox isolation and permission requests are not available yet. No permissions can be granted or revoked."] = ["Sandbox isolation and permission requests are not available yet. No permissions can be granted or revoked.", "Sandbox-isolatie en toestemmingsverzoeken zijn nog niet beschikbaar. Er kunnen nog geen toestemmingen worden verleend of ingetrokken.", "Sandbox-Isolation und Berechtigungsanfragen sind noch nicht verfügbar. Es können noch keine Berechtigungen erteilt oder entzogen werden.", "L’isolation du bac à sable et les demandes d’autorisation ne sont pas encore disponibles. Aucune autorisation ne peut être accordée ou révoquée."],
        ["Sandbox is not implemented yet; OpenCode will not start while this is enabled."] = ["Sandbox is not implemented yet; OpenCode will not start while this is enabled.", "De sandbox is nog niet geïmplementeerd. OpenCode start niet zolang deze optie aanstaat.", "Die Sandbox ist noch nicht implementiert. OpenCode wird nicht gestartet, solange diese Option aktiviert ist.", "Le bac à sable n’est pas encore implémenté. OpenCode ne démarrera pas tant que cette option est activée."],
        ["Off: OpenCode runs with your normal Windows user access."] = ["Off: OpenCode runs with your normal Windows user access.", "Uit: OpenCode draait met de normale toegangsrechten van je Windows-account.", "Aus: OpenCode läuft mit den normalen Zugriffsrechten Ihres Windows-Kontos.", "Désactivé : OpenCode s’exécute avec les droits normaux de votre compte Windows."],
        ["OpenCode sandbox is enabled, but isolated execution is not available yet. OpenCode was not started."] = ["OpenCode sandbox is enabled, but isolated execution is not available yet. OpenCode was not started.", "De OpenCode-sandbox staat aan, maar geïsoleerd uitvoeren is nog niet beschikbaar. OpenCode is niet gestart.", "Die OpenCode-Sandbox ist aktiviert, aber isolierte Ausführung ist noch nicht verfügbar. OpenCode wurde nicht gestartet.", "Le bac à sable OpenCode est activé, mais l’exécution isolée n’est pas encore disponible. OpenCode n’a pas démarré."],
